content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --danger-color: #ef4444;
  --radius: 8px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1000px;
  margin: 0 auto;
  padding: 20px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.header {
  background-color: var(--card-bg);
  padding: 20px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  text-align: center;
}

.header h1 {
  font-size: 1.75rem;
  color: var(--primary-color);
  margin-bottom: 5px;
}

.header p {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.main-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

@media (max-width: 768px) {
  .main-layout {
    grid-template-columns: 1fr;
  }
}

.chart-section, .list-section {
  background-color: var(--card-bg);
  padding: 20px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.chart-section h2, .list-section h2 {
  font-size: 1.25rem;
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 8px;
}

.amount-display {
  background-color: #e0e7ff;
  border-left: 4px solid var(--primary-color);
  padding: 12px 16px;
  border-radius: 4px;
  font-size: 1.1rem;
  font-weight: bold;
  color: var(--primary-color);
}

.expense-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  cursor: pointer;
  transition: all 0.2s ease;
  background-color: #fafafa;
}

.expense-item:hover {
  background-color: #f3f4f6;
  border-color: var(--text-muted);
}

.expense-item-active {
  background-color: #e0e7ff !important;
  border-color: var(--primary-color) !important;
  box-shadow: 0 0 0 1px var(--primary-color);
}

.form-container {
  background-color: var(--card-bg);
  padding: 20px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.form-container h2 {
  font-size: 1.25rem;
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 8px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.form-group label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-main);
}

.form-group input,
.form-group select {
  padding: 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  font-size: 1rem;
}

.form-group input:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 2px rgba(79, 70, 229, 0.2);
}

.btn {
  padding: 10px 16px;
  border: none;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-danger {
  background-color: var(--danger-color);
  color: #ffffff;
  padding: 6px 10px;
  font-size: 0.85rem;
}

.btn-danger:hover {
  background-color: #dc2626;
}

.expense-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 300px;
  overflow-y: auto;
}

export interface ExpenseItem {
  id: string;
  category: string;
  amount: number;
  color: string;
}

import { useState } from 'react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { ExpenseItem } from './types';

const INITIAL_EXPENSES: ExpenseItem[] = [
  { id: '1', category: '食費', amount: 45000, color: '#4f46e5' },
  { id: '2', category: '家賃', amount: 80000, color: '#10b981' },
  { id: '3', category: '光熱費', amount: 12000, color: '#f59e0b' },
  { id: '4', category: '娯楽', amount: 15000, color: '#ef4444' },
  { id: '5', category: '交通費', amount: 8000, color: '#8b5cf6' },
];

export default function App() {
  const [expenses, setExpenses] = useState<ExpenseItem[]>(INITIAL_EXPENSES);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const [category, setCategory] = useState('');
  const [amount, setAmount] = useState('');
  const [color, setColor] = useState('#4f46e5');

  const selectedItem = expenses.find((item) => item.id === selectedId);

  const handleAddExpense = (e: React.FormEvent) => {
    e.preventDefault();
    if (!category || !amount) return;

    const newItem: ExpenseItem = {
      id: Date.now().toString(),
      category,
      amount: Number(amount),
      color,
    };

    setExpenses([...expenses, newItem]);
    setCategory('');
    setAmount('');
  };

  const handleDeleteExpense = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setExpenses(expenses.filter((item) => item.id !== id));
    if (selectedId === id) {
      setSelectedId(null);
    }
  };

  const totalAmount = expenses.reduce((sum, item) => sum + item.amount, 0);

  return (
    <div className="app-container">
      <header className="header">
        <h1>家計簿アプリケーション</h1>
        <p>支出内訳の確認と管理を行います</p>
      </header>

      <div className="main-layout">
        <section className="chart-section">
          <h2>支出内訳グラフ</h2>
          <div style={{ width: '100%', height: 250 }}>
            {expenses.length > 0 ? (
              <ResponsiveContainer>
                <PieChart>
                  <Pie
                    data={expenses}
                    dataKey="amount"
                    nameKey="category"
                    cx="50%"
                    cy="50%"
                    outerRadius={80}
                    label
                  >
                    {expenses.map((entry) => (
                      <Cell key={`cell-${entry.id}`} fill={entry.color} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(value: number) => `¥${value.toLocaleString()}`} />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            ) : (
              <p style={{ textAlign: 'center', color: 'var(--text-muted)' }}>データがありません</p>
            )}
          </div>
          <p style={{ textAlign: 'center', fontWeight: 'bold' }}>
            総支出: ¥{totalAmount.toLocaleString()}
          </p>
        </section>

        <section className="list-section">
          <h2>支出項目リスト</h2>
          {selectedItem && (
            <div className="amount-display">
              {selectedItem.category}: ¥{selectedItem.amount.toLocaleString()}
            </div>
          )}
          <div className="expense-list">
            {expenses.map((item) => {
              const isSelected = item.id === selectedId;
              return (
                <div
                  key={item.id}
                  className={`expense-item ${isSelected ? 'expense-item-active' : ''}`}
                  onClick={() => setSelectedId(item.id)}
                >
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <span
                      style={{
                        width: '12px',
                        height: '12px',
                        borderRadius: '50%',
                        backgroundColor: item.color,
                        display: 'inline-block',
                      }}
                    />
                    <span>{item.category}</span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <span>¥{item.amount.toLocaleString()}</span>
                    <button
                      className="btn btn-danger"
                      onClick={(e) => handleDeleteExpense(item.id, e)}
                    >
                      削除
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </section>
      </div>

      <section className="form-container">
        <h2>新しい支出の追加</h2>
        <form onSubmit={handleAddExpense} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          <div className="form-group">
            <label htmlFor="category">カテゴリ名</label>
            <input
              id="category"
              type="text"
              value={category}
              onChange={(e) => setCategory(e.target.value)}
              placeholder="例: 衣服、交際費など"
              required
            />
          </div>
          <div className="form-group">
            <label htmlFor="amount">金額 (円)</label>
            <input
              id="amount"
              type="number"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              placeholder="例: 5000"
              required
            />
          </div>
          <div className="form-group">
            <label htmlFor="color">表示カラー</label>
            <input
              id="color"
              type="color"
              value={color}
              onChange={(e) => setColor(e.target.value)}
            />
          </div>
          <button type="submit" className="btn btn-primary">
            追加する
          </button>
        </form>
      </section>
    </div>
  );
}
